import "server-only";

import { services } from "@/lib/api";
import { must } from "@/lib/backend";
import type { Service, Slot, Client, Booking } from "@/lib/types";

export type ClientPickerProps = {
    clients: Array<Pick<Client, "id" | "name">>;
};

export async function readClientPicker(clients: Client[]): Promise<ClientPickerProps> {
    return {
        clients: await Promise.all(
            clients.map(async (record) => {
                return {
                    id: record.id,
                    name: record.name,
                };
            }),
        ),
    };
}

