export type SlotPickerProps = {
    open: Array<Pick<Slot, "id" | "starts_at"> & {
        service: Pick<Service, "id" | "name"> & { href: string };
    }>;
};

export async function readSlotPicker(open: Slot[]): Promise<SlotPickerProps> {
    return {
        open: await Promise.all(
            open.map(async (record) => {
                const [service] = await Promise.all([
                    must(services.get(record.service_id)),
                ]);
                return {
                    id: record.id,
                    starts_at: record.starts_at,
                    service: { id: service.id, name: service.name, href: `/services/${encodeURIComponent(service.id)}` },
                };
            }),
        ),
    };
}

